import type { Metadata } from "next";
import { getLocale, getTranslations } from "next-intl/server";

import { getAuthSession } from "@intelligo-dev/auth";

import { redirect } from "@/i18n/navigation";
import { AuthCard } from "@/components/auth/auth-card";
import { SocialLoginButtons } from "@/components/auth/social-login-buttons";
import { SignupForm } from "@/components/auth/signup-form";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("auth-signup");
  return {
    title: t("metadata.title"),
    description: t("metadata.description"),
  };
}

/**
 * A signed-in visitor has no use for this page.
 *
 * Done here rather than in middleware because middleware only sees the
 * session cookie, not the session. Redirecting on the cookie while the
 * authenticated app layout redirects on the real session is an infinite
 * loop for anyone holding a stale one — revoked elsewhere, expired row,
 * rotated secret — and the loop locks them out of the page that would
 * fix it.
 */
async function redirectIfSignedIn(): Promise<void> {
  if (await getAuthSession())
    redirect({ href: "/dashboard", locale: await getLocale() });
}

export default async function SignupPage() {
  await redirectIfSignedIn();

  const t = await getTranslations("auth-signup");

  // OAuth provider buttons only render for providers actually configured
  // on the server — checked here, not in the client component, so an
  // unconfigured client id/secret never reaches the browser at all.
  const providers: string[] = [];
  if (process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET) {
    providers.push("google");
  }
  if (process.env.GITHUB_CLIENT_ID && process.env.GITHUB_CLIENT_SECRET) {
    providers.push("github");
  }

  return (
    <AuthCard title={t("card.title")} description={t("card.description")}>
      <div className="space-y-6">
        <SocialLoginButtons providers={providers} />
        <SignupForm />
      </div>
    </AuthCard>
  );
}

"use client";

/**
 * Name + email + password + confirm registration form. Calls the
 * Better-Auth client SDK (`@intelligo-dev/auth/client`) directly — no raw
 * `fetch("/api/auth/*")`.
 *
 * Post-signup routing depends on whether the server has email
 * verification turned on (`emailAndPassword.requireEmailVerification`
 * in `@intelligo-dev/auth`'s server config). When it's on, `signUp.email()`
 * creates the user but returns `token: null` — no session — instead of
 * signing them in, so this form sends the visitor to `/verify-email`
 * with their address instead of the dashboard. When it's off (or the
 * address is exempt), a session comes back immediately and the form
 * goes straight to the dashboard.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";

import { authClient } from "@intelligo-dev/auth/client";

import { Link, useRouter } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Spinner } from "@/components/ui/spinner";
import { signupSchema, type SignupInput } from "@/lib/auth-validation";

export function SignupForm() {
  const t = useTranslations("auth-signup");
  const router = useRouter();
  const [formError, setFormError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<SignupInput>({
    resolver: zodResolver(signupSchema),
  });

  async function onSubmit(data: SignupInput) {
    try {
      setFormError(null);
      setIsLoading(true);

      const result = await authClient.signUp.email({
        name: data.name,
        email: data.email,
        password: data.password,
        callbackURL: "/dashboard",
      });

      if (result.error) {
        setFormError(
          result.error.message?.includes("already")
            ? t("signupForm.errors.accountExists")
            : (result.error.message ?? t("signupForm.errors.unexpected"))
        );
        setIsLoading(false);
        return;
      }

      if (!result.data?.token) {
        router.push(`/verify-email?email=${encodeURIComponent(data.email)}`);
        return;
      }

      router.push("/dashboard");
    } catch (error) {
      console.error("Signup error:", error);
      setFormError(t("signupForm.errors.unexpected"));
      setIsLoading(false);
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate className="space-y-4">
      {formError && (
        <Alert variant="destructive">
          <AlertDescription>{formError}</AlertDescription>
        </Alert>
      )}

      <div className="space-y-2">
        <Label htmlFor="name">{t("signupForm.nameLabel")}</Label>
        <Input
          id="name"
          type="text"
          autoComplete="name"
          disabled={isLoading}
          aria-invalid={errors.name ? true : undefined}
          aria-describedby={errors.name ? "name-error" : undefined}
          {...register("name")}
        />
        {errors.name && (
          <p id="name-error" className="text-sm text-destructive">
            {t(`validation.${errors.name.message}`)}
          </p>
        )}
      </div>

      <div className="space-y-2">
        <Label htmlFor="email">{t("signupForm.emailLabel")}</Label>
        <Input
          id="email"
          type="email"
          autoComplete="email"
          disabled={isLoading}
          aria-invalid={errors.email ? true : undefined}
          aria-describedby={errors.email ? "email-error" : undefined}
          {...register("email")}
        />
        {errors.email && (
          <p id="email-error" className="text-sm text-destructive">
            {t(`validation.${errors.email.message}`)}
          </p>
        )}
      </div>

      <div className="space-y-2">
        <Label htmlFor="password">{t("signupForm.passwordLabel")}</Label>
        <Input
          id="password"
          type="password"
          autoComplete="new-password"
          disabled={isLoading}
          aria-invalid={errors.password ? true : undefined}
          aria-describedby={errors.password ? "password-error" : undefined}
          {...register("password")}
        />
        {errors.password && (
          <p id="password-error" className="text-sm text-destructive">
            {t(`validation.${errors.password.message}`)}
          </p>
        )}
      </div>

      <div className="space-y-2">
        <Label htmlFor="confirmPassword">
          {t("signupForm.confirmPasswordLabel")}
        </Label>
        <Input
          id="confirmPassword"
          type="password"
          autoComplete="new-password"
          disabled={isLoading}
          aria-invalid={errors.confirmPassword ? true : undefined}
          aria-describedby={
            errors.confirmPassword ? "confirm-password-error" : undefined
          }
          {...register("confirmPassword")}
        />
        {errors.confirmPassword && (
          <p id="confirm-password-error" className="text-sm text-destructive">
            {t(`validation.${errors.confirmPassword.message}`)}
          </p>
        )}
      </div>

      <Button type="submit" className="w-full" disabled={isLoading}>
        {isLoading ? (
          <span className="flex items-center justify-center gap-2">
            <Spinner />
            {t("signupForm.submitting")}
          </span>
        ) : (
          t("signupForm.submit")
        )}
      </Button>

      <p className="text-center text-sm text-muted-foreground">
        {t("signupForm.alreadyHaveAccount")}{" "}
        <Link
          href="/login"
          className="font-medium text-primary hover:text-primary/80"
        >
          {t("signupForm.logInLink")}
        </Link>
      </p>
    </form>
  );
}

{
  "metadata": {
    "title": "Sign up",
    "description": "Create an account."
  },
  "card": {
    "title": "Create an account",
    "description": "Get started for free"
  },
  "signupForm": {
    "nameLabel": "Name",
    "emailLabel": "Email",
    "passwordLabel": "Password",
    "confirmPasswordLabel": "Confirm password",
    "submit": "Create account",
    "submitting": "Creating account…",
    "alreadyHaveAccount": "Already have an account?",
    "logInLink": "Log in",
    "errors": {
      "accountExists": "An account with this email already exists.",
      "unexpected": "Something went wrong. Please try again."
    }
  },
  "validation": {
    "nameTooShort": "Name must be at least 2 characters",
    "nameTooLong": "Name must be less than 50 characters",
    "emailInvalid": "Please enter a valid email address",
    "passwordTooShort": "Password must be at least 8 characters",
    "passwordTooLong": "Password must be less than 128 characters",
    "passwordWeak": "Password must contain at least 1 uppercase letter, 1 lowercase letter, and 1 number",
    "passwordMismatch": "Passwords do not match"
  }
}
